    @push('script')
        <script>
            document.addEventListener('DOMContentLoaded', () => {
                // انتخاب تمام کانتینرهای ستاره‌ها
                const ratingContainers = document.querySelectorAll('.rating-container');

                ratingContainers.forEach(container => {
                    // برای هر کانتینر، تمام ستاره‌ها را انتخاب می‌کنیم
                    const stars = container.querySelectorAll('.star');

                    // اضافه کردن Event Listener برای هر ستاره
                    stars.forEach(star => {
                        star.addEventListener('click', (event) => {
                            const clickedStar = event.currentTarget;
                            const value = parseInt(clickedStar.dataset.value); // مقدار data-value ستاره کلیک‌شده

                            // تمام ستاره‌ها را به حالت پیش‌فرض (خالی) برمی‌گرداند
                            stars.forEach(s => {
                                s.classList.remove('text-yellow-500');
                                s.classList.add('text-gray-400');
                            });

                            // ستاره‌های مربوطه را پررنگ می‌کند
                            // چون جهت از چپ به راست است، و پر شدن از راست به چپ، منطق را برعکس می‌کنیم.
                            const totalStars = stars.length;
                            const startIndex = totalStars - value;

                            for (let i = startIndex; i < totalStars; i++) {
                                stars[i].classList.remove('text-gray-400');
                                stars[i].classList.add('text-yellow-500');
                            }

                            // می‌توانید مقدار نهایی را به صورت یک متغیر یا فیلد پنهان ذخیره کنید
                            console.log(`امتیاز انتخاب شده: ${value}`);
                        });
                    });
                });
            });
        </script>
    @endpush
</div>
